Action.Str:
var sender = global("SMSRF");
var message = global("SMSRB");
var receivedMillis = global("TIMEMS");
var locationObject;
var latitude = Number(typeof gl_latitude !== "undefined" ? gl_latitude : NaN);
var longitude = Number(typeof gl_longitude !== "undefined" ? gl_longitude : NaN);
var accuracy = Number(typeof gl_coordinates_accuracy !== "undefined" ? gl_coordinates_accuracy : NaN);
if (isFinite(latitude) && isFinite(longitude)) {
  locationObject = { latitude: latitude, longitude: longitude };
  if (isFinite(accuracy) && accuracy >= 0) locationObject.accuracyMeters = accuracy;
}
var eventObject = {
  eventId: String(sender) + "-" + String(receivedMillis),
  sender: String(sender),
  message: String(message),
  receivedAt: new Date(Number(receivedMillis)).toISOString()
};
if (locationObject) eventObject.location = locationObject;
var payload = JSON.stringify(eventObject);
setLocal("%payload", payload);

if (typeof http_response_code === "undefined" || String(http_response_code) !== "202") {
  var detail = typeof errmsg !== "undefined" ? errmsg : (typeof http_data !== "undefined" ? http_data : "No response");
  flashLong("Actual SMS upload failed: " + detail);
}
